-- The core team's decision on a submitted update: who made it and when, a response the core team
-- sends with revisions, and the update summary as a flaggable task. No published view reads
-- submissions or their responses, and internal_api writes both under its table-level grants.
ALTER TABLE "audit_log" DROP CONSTRAINT "audit_log_action_check";--> statement-breakpoint
ALTER TABLE "indicator_version_submission_flag" DROP CONSTRAINT "indicator_version_submission_flag_task_key_check";--> statement-breakpoint
ALTER TABLE "indicator_version_submission_response" ALTER COLUMN "reviewer_id" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "indicator_version_submission" ADD COLUMN "update_decided_by" uuid;--> statement-breakpoint
ALTER TABLE "indicator_version_submission" ADD COLUMN "update_decided_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "indicator_version_submission_response" ADD COLUMN "core_team_member_id" uuid;--> statement-breakpoint
ALTER TABLE "indicator_version_submission" ADD CONSTRAINT "indicator_version_submission_update_decided_by_fk" FOREIGN KEY ("update_decided_by") REFERENCES "public"."app_user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "indicator_version_submission_response" ADD CONSTRAINT "indicator_version_submission_response_core_team_member_fk" FOREIGN KEY ("core_team_member_id") REFERENCES "public"."app_user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_action_check" CHECK ("audit_log"."action" IN ('topic.created', 'topic.updated', 'topic.deleted', 'indicator.draft_created', 'indicator.draft_updated', 'indicator.draft_created_from_published', 'indicator.data_table_confirmed', 'indicator.submitted', 'indicator.submission_withdrawn', 'indicator.update_sent_to_imrg', 'indicator.update_revisions_requested', 'indicator.update_approved', 'indicator.reviewers_assigned', 'indicator.review_feedback_given', 'indicator.changes_requested', 'indicator.approved', 'indicator.resubmitted', 'indicator.revision_response_updated', 'indicator.publication_scheduled', 'indicator.publication_date_changed', 'indicator.published', 'indicator.review_note_added', 'indicator.review_note_updated', 'upload_batch.loaded', 'upload_batch.refused', 'upload_batch.deleted'));--> statement-breakpoint
ALTER TABLE "indicator_version_submission" ADD CONSTRAINT "indicator_version_submission_update_decided_check" CHECK (("indicator_version_submission"."update_decision" IS NULL) = ("indicator_version_submission"."update_decided_by" IS NULL) AND ("indicator_version_submission"."update_decided_by" IS NULL) = ("indicator_version_submission"."update_decided_at" IS NULL));--> statement-breakpoint
ALTER TABLE "indicator_version_submission_flag" ADD CONSTRAINT "indicator_version_submission_flag_task_key_check" CHECK ("indicator_version_submission_flag"."task_key" IN ('name', 'data-table', 'definition-and-rationale', 'polarity', 'data-quality', 'numerator', 'denominator', 'calculation', 'confidence-intervals', 'update-frequency', 'value-type-and-units', 'period-type', 'other-notes-and-caveats', 'publishing-date', 'copyright-and-data-reuse', 'benchmarking', 'sex-gender-and-ethnicity', 'ages', 'tagging', 'update-summary'));--> statement-breakpoint
ALTER TABLE "indicator_version_submission_response" ADD CONSTRAINT "indicator_version_submission_response_responder_check" CHECK (("indicator_version_submission_response"."reviewer_id" IS NULL) <> ("indicator_version_submission_response"."core_team_member_id" IS NULL) AND ("indicator_version_submission_response"."core_team_member_id" IS NULL OR "indicator_version_submission_response"."kind" = 'pre_imrg_feedback'));
